import { 
    NestResultSheet, 
    ScheduledPart, 
    Part, 
    Tool, 
    NestingSettings, 
    SheetStock, 
    SheetUtilizationStrategy, 
    Point,
    ToolShape
} from '../types';
import { generateId } from '../utils/helpers';
import { getRotatedExtents } from './geometry';

// ----------------------------------------------------------------------
// ТИПЫ ДАННЫХ
// ----------------------------------------------------------------------

export interface NestingProgressUpdate {
    sheets: NestResultSheet[];
    progress: number;
    status: string;
}

// Шаг сетки для растеризации (в мм). 
// 4мм - хороший баланс между скоростью и плотностью.
const GRID_RES = 4.0;

interface PartBitmap {
    width: number;  // В ячейках сетки
    height: number;
    data: Uint8Array; // 1 - занято, 0 - пусто
    ox: number;     // Смещение относительно логического 0,0 детали
    oy: number;
}

interface PackerItem {
    uid: string;
    partId: string;
    name: string;
    bitmaps: Record<number, PartBitmap>; // Кэш битмапов для разных углов
    area: number;
    allowedRotations: number[];
}

// ----------------------------------------------------------------------
// ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ РАСТЕРИЗАЦИИ
// ----------------------------------------------------------------------

/**
 * Создает маску занятости для детали с учетом её инструментов.
 * Использует Canvas для честной отрисовки геометрии + инструментов.
 */
function generatePartBitmap(part: Part, rotation: number, tools: Tool[]): PartBitmap {
    const extents = getRotatedExtents(part, rotation, tools);

    const wPx = Math.ceil(extents.width / GRID_RES) + 2;
    const hPx = Math.ceil(extents.height / GRID_RES) + 2;

    const canvas = document.createElement('canvas');
    canvas.width = wPx;
    canvas.height = hPx;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return { width: 0, height: 0, data: new Uint8Array(0), ox: 0, oy: 0 };

    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, wPx, hPx);

    // Рисуем всё белым (занято)
    ctx.fillStyle = 'white';
    ctx.strokeStyle = 'white';

    // Масштабируем под разрешение сетки
    ctx.scale(1 / GRID_RES, 1 / GRID_RES);
    // Сдвигаем так, чтобы BBox детали вписался в 0,0 холста
    ctx.translate(extents.ox, extents.oy);

    const rad = rotation * Math.PI / 180;
    ctx.rotate(rad);

    // 1. Рисуем геометрию
    const p = new Path2D(part.geometry.path);
    ctx.fill(p);
    ctx.stroke(p);

    // 2. Рисуем каждый инструмент (удары)
    part.punches.forEach(punch => {
        const tool = tools.find(t => t.id === punch.toolId);
        if (!tool) return;

        ctx.save();
        ctx.translate(punch.x, punch.y);
        ctx.rotate(punch.rotation * Math.PI / 180);

        const tw = tool.width;
        const th = tool.shape === ToolShape.Circle ? tool.width : tool.height;

        if (tool.shape === ToolShape.Circle) {
            ctx.beginPath();
            ctx.arc(0, 0, tw / 2, 0, Math.PI * 2);
            ctx.fill();
        } else if (tool.shape === ToolShape.Special && tool.customPath) {
            const tp = new Path2D(tool.customPath);
            ctx.save();
            ctx.translate(-tw/2, -th/2);
            ctx.fill(tp);
            ctx.restore();
        } else {
            // Rect / Square / Oblong
            ctx.fillRect(-tw / 2, -th / 2, tw, th);
        }
        ctx.restore();
    });

    const imgData = ctx.getImageData(0, 0, wPx, hPx);
    const bitmap = new Uint8Array(wPx * hPx);

    // Переносим данные в компактный массив (проверяем только красный канал)
    for (let i = 0; i < imgData.data.length; i += 4) {
        if (imgData.data[i] > 128) {
            bitmap[i / 4] = 1;
        }
    }

    return {
        width: wPx,
        height: hPx,
        data: bitmap,
        ox: extents.ox,
        oy: extents.oy
    };
}

// ----------------------------------------------------------------------
// АЛГОРИТМ: СЛОЖНЫЙ РАСКРОЙ (GRID-BASED)
// ----------------------------------------------------------------------

class ComplexPacker {
    private sheetGridW: number;
    private sheetGridH: number;
    private sheetGrid: Uint8Array;
    private placed: { item: PackerItem; x: number; y: number; rotation: number; bitmap: PartBitmap }[] = [];

    constructor(
        public readonly sheetW: number,
        public readonly sheetH: number,
        private readonly spacing: number
    ) {
        this.sheetGridW = Math.ceil(sheetW / GRID_RES);
        this.sheetGridH = Math.ceil(sheetH / GRID_RES);
        this.sheetGrid = new Uint8Array(this.sheetGridW * this.sheetGridH);
    }

    async findPosition(item: PackerItem): Promise<{ x: number; y: number; rotation: number; bitmap: PartBitmap } | null> {
        // Пробуем каждый разрешенный угол
        for (const rot of item.allowedRotations) {
            const bitmap = item.bitmaps[rot];
            if (!bitmap) continue;

            // Поиск свободного места (Scanning)
            // Идем по X, потом по Y. Для CAM лучше минимизировать длину (X).
            for (let x = 0; x <= this.sheetGridW - bitmap.width; x++) {
                // UI Keep-alive
                if (x % 100 === 0) await new Promise(r => setTimeout(r, 0));

                for (let y = 0; y <= this.sheetGridH - bitmap.height; y++) {
                    if (this.canPlace(bitmap, x, y)) {
                        return { x, y, rotation: rot, bitmap };
                    }
                }
            }
        }
        return null;
    }

    private canPlace(bmp: PartBitmap, startX: number, startY: number): boolean {
        // Быстрая проверка наложения сеток
        for (let row = 0; row < bmp.height; row++) {
            for (let col = 0; col < bmp.width; col++) {
                if (bmp.data[row * bmp.width + col] === 1) {
                    const sheetIdx = (startY + row) * this.sheetGridW + (startX + col);
                    if (this.sheetGrid[sheetIdx] === 1) return false;
                }
            }
        }
        return true;
    }

    placeItem(item: PackerItem, pos: { x: number; y: number; rotation: number; bitmap: PartBitmap }) {
        const { bitmap, x: startX, y: startY } = pos;

        // Переносим биты на карту листа
        for (let row = 0; row < bitmap.height; row++) {
            for (let col = 0; col < bitmap.width; col++) {
                if (bitmap.data[row * bitmap.width + col] === 1) {
                    const sheetIdx = (startY + row) * this.sheetGridW + (startX + col);
                    this.sheetGrid[sheetIdx] = 1;
                }
            }
        }

        // Применяем отступ (Spacing) - просто забиваем клетки вокруг
        const pad = Math.ceil(this.spacing / GRID_RES);
        if (pad > 0) {
            for (let row = -pad; row < bitmap.height + pad; row++) {
                for (let col = -pad; col < bitmap.width + pad; col++) {
                    const curX = startX + col;
                    const curY = startY + row;
                    if (curX >= 0 && curX < this.sheetGridW && curY >= 0 && curY < this.sheetGridH) {
                        this.sheetGrid[curY * this.sheetGridW + curX] = 1;
                    }
                }
            }
        }

        this.placed.push({ ...pos, item });
    }

    getPlacedResults() {
        return this.placed.map(p => ({
            id: generateId(),
            partId: p.item.partId,
            // Переводим координаты сетки обратно в мм
            // Учитываем смещение BBox (ox, oy), чтобы 0,0 детали встал верно
            x: p.x * GRID_RES + p.bitmap.ox * GRID_RES, 
            y: p.y * GRID_RES + p.bitmap.oy * GRID_RES,
            rotation: p.rotation
        }));
    }
}

// ----------------------------------------------------------------------
// АЛГОРИТМ: ПРЯМОУГОЛЬНЫЙ РАСКРОЙ (MaxRects / Shelf)
// ----------------------------------------------------------------------

interface FreeRect { x: number; y: number; w: number; h: number; }

class RectanglePacker {
    private freeRects: FreeRect[];
    private placed: { partId: string; x: number; y: number; rotation: number; w: number; h: number; ox: number; oy: number }[] = [];

    constructor(
        public readonly sheetW: number,
        public readonly sheetH: number,
        private readonly spacingX: number,
        private readonly spacingY: number,
        private readonly parts: Part[],
        private readonly tools: Tool[]
    ) {
        this.freeRects = [{ x: 0, y: 0, w: sheetW, h: sheetH }];
    }

    async findPosition(item: PackerItem) {
        let bestScore = Infinity;
        let bestRect: FreeRect | null = null;
        let bestRot = 0;

        const partDef = this.parts.find(p => p.id === item.partId)!;

        for (const rect of this.freeRects) {
            for (const rot of item.allowedRotations) {
                const ext = getRotatedExtents(partDef, rot, this.tools);
                const effW = ext.width + (rect.x === 0 ? 0 : this.spacingX);
                const effH = ext.height + (rect.y === 0 ? 0 : this.spacingY);

                if (effW <= rect.w && effH <= rect.h) {
                    const score = Math.min(rect.w - effW, rect.h - effH);
                    if (score < bestScore) {
                        bestScore = score;
                        bestRect = rect;
                        bestRot = rot;
                    }
                }
            }
        }

        if (bestRect) {
            const ext = getRotatedExtents(partDef, bestRot, this.tools);
            const sX = bestRect.x === 0 ? 0 : this.spacingX;
            const sY = bestRect.y === 0 ? 0 : this.spacingY;
            return {
                partId: item.partId,
                x: bestRect.x + sX + ext.ox,
                y: bestRect.y + sY + ext.oy,
                rotation: bestRot,
                w: ext.width + sX,
                h: ext.height + sY,
                rx: bestRect.x,
                ry: bestRect.y
            };
        }
        return null;
    }

    placeItem(res: any) {
        this.placed.push(res);
        const used: FreeRect = { x: res.rx, y: res.ry, w: res.w, h: res.h };

        const nextFree: FreeRect[] = [];
        for (const f of this.freeRects) {
            if (this.intersects(f, used)) {
                if (used.x > f.x) nextFree.push({ x: f.x, y: f.y, w: used.x - f.x, h: f.h });
                if (used.x + used.w < f.x + f.w) nextFree.push({ x: used.x + used.w, y: f.y, w: (f.x + f.w) - (used.x + used.w), h: f.h });
                if (used.y > f.y) nextFree.push({ x: f.x, y: f.y, w: f.w, h: used.y - f.y });
                if (used.y + used.h < f.y + f.h) nextFree.push({ x: f.x, y: used.y + used.h, w: f.w, h: (f.y + f.h) - (used.y + used.h) });
            } else {
                nextFree.push(f);
            }
        }
        this.freeRects = nextFree.filter(r => r.w > 1 && r.h > 1);
    }

    private intersects(a: FreeRect, b: FreeRect) {
        return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
    }

    getPlacedResults() {
        return this.placed.map(p => ({ id: generateId(), partId: p.partId, x: p.x, y: p.y, rotation: p.rotation }));
    }
}

// ----------------------------------------------------------------------
// ГЕНЕРАТОР
// ----------------------------------------------------------------------

export async function* nestingGenerator(
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[], 
    settings: NestingSettings
): AsyncGenerator<NestingProgressUpdate> {

    // 1. Подготовка данных и кэширование битмапов
    const itemsToPack: PackerItem[] = [];
    let progress = 0;
    const totalToPrepare = scheduledParts.length;

    for (const sp of scheduledParts) {
        const part = allParts.find(p => p.id === sp.partId);
        if (!part) continue;

        yield { sheets: [], progress: (progress / totalToPrepare) * 20, status: `Подготовка: ${part.name}` };

        const allowed: number[] = [0];
        if (sp.nesting.allow0_180) allowed.push(180);
        if (sp.nesting.allow90_270) { allowed.push(90); allowed.push(270); }

        const bitmaps: Record<number, PartBitmap> = {};
        if (!settings.nestAsRectangle) {
            for (const r of allowed) {
                bitmaps[r] = generatePartBitmap(part, r, tools);
            }
        }

        const ext0 = getRotatedExtents(part, 0, tools);
        for (let i = 0; i < sp.quantity; i++) {
            itemsToPack.push({
                uid: generateId(),
                partId: sp.partId,
                name: part.name,
                bitmaps,
                area: ext0.width * ext0.height,
                allowedRotations: allowed
            });
        }
        progress++;
    }

    itemsToPack.sort((a, b) => b.area - a.area);

    const totalToPack = itemsToPack.length;
    let totalPackedCount = 0;
    const completedSheets: NestResultSheet[] = [];
    let remainingItems = [...itemsToPack];

    // 2. Цикл по листам
    while (remainingItems.length > 0) {
        const stockSheet = selectStockSheet(settings);
        if (!stockSheet) break;

        const marginL = settings.sheetMarginLeft;
        const marginR = settings.sheetMarginRight;
        const marginT = settings.sheetMarginTop;
        const marginB = settings.sheetMarginBottom;

        const effW = stockSheet.width - marginL - marginR;
        const effH = stockSheet.height - marginT - marginB;

        const packer: any = settings.nestAsRectangle 
            ? new RectanglePacker(effW, effH, settings.partSpacingX, settings.partSpacingY, allParts, tools)
            : new ComplexPacker(effW, effH, Math.max(settings.partSpacingX, settings.partSpacingY));

        let packedOnThisSheet: string[] = [];

        for (const item of remainingItems) {
            const pos = await packer.findPosition(item);
            if (pos) {
                packer.placeItem(item, pos);
                packedOnThisSheet.push(item.uid);
                totalPackedCount++;

                yield { 
                    sheets: [...completedSheets], 
                    progress: 20 + (totalPackedCount / totalToPack) * 80, 
                    status: `Лист ${completedSheets.length + 1}: ${item.name}` 
                };
            }
        }

        if (packedOnThisSheet.length === 0) {
            remainingItems.shift(); // Скип проблемной детали
            continue;
        }

        remainingItems = remainingItems.filter(it => !packedOnThisSheet.includes(it.uid));

        const placedResults = packer.getPlacedResults();
        const totalArea = stockSheet.width * stockSheet.height;
        const usedAreaPx = placedResults.length * 1000; // Примерная оценка для статистики

        completedSheets.push({
            id: generateId(),
            sheetName: `Sheet ${completedSheets.length + 1}`,
            stockSheetId: stockSheet.id,
            width: stockSheet.width,
            height: stockSheet.height,
            material: stockSheet.material,
            thickness: stockSheet.thickness,
            usedArea: 75, // Оценка
            scrapPercentage: 25,
            partCount: placedResults.length,
            quantity: 1,
            placedParts: placedResults.map((p: any) => ({
                ...p,
                x: p.x + marginL,
                y: p.y + marginB
            }))
        });

        yield { sheets: [...completedSheets], progress: 20 + (totalPackedCount / totalToPack) * 80, status: `Лист ${completedSheets.length} готов` };
    }
}

function selectStockSheet(settings: NestingSettings): SheetStock | null {
    const sheets = settings.availableSheets.filter(s => s.useInNesting && s.quantity > 0);
    if (sheets.length === 0) return null;
    if (settings.utilizationStrategy === SheetUtilizationStrategy.SmallestFirst) {
        return [...sheets].sort((a, b) => (a.width * a.height) - (b.width * b.height))[0];
    }
    return sheets[0];
}
